package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.Sheets;
import org.springframework.stereotype.Service;

/** Works out a sheet's figures the way the screen shows them (claimed, due-total, overdue-total, and their totals). */
@Service
public class Rollup {

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final People people;
    private final Claims claims;
    private final Rates rates;
    private final Sheets sheets;
    private final Settings settings;

    public Rollup(People people, Claims claims, Rates rates, Sheets sheets, Settings settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's alert threshold; null when alerts are off. */
    public BigDecimal alertThreshold(String sheetId) {
        return settings.alertThreshold(sheetId);
    }

    public Figures figures(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Claim> counting = claims.list(sheetId).stream()
                .filter(c -> c.status().counts()).toList();
        Map<Long, Figures.PersonFigures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean anyFigure = false;
            for (Claim claim : counting) {
                if (claim.personId() != person.id() || !counts(claim, person, today)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                BigDecimal figure = figure(claim, person, today);
                if (figure != null) {
                    due = due.add(figure);
                    anyFigure = true;
                    if (settings.overdue(claim, today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // With no rate today and no figure, the due-total is n/a.
            boolean none = !anyFigure && rates.on(sheetId, person.gradeOn(today), today) == null;
            // Otherwise it is held to the sheet's cap.
            due = settings.capped(sheetId, due);
            claimedTotal = claimedTotal.add(claimed);
            if (!none) {
                dues.add(due);
            }
            overdues.add(overdue);
            figures.put(person.id(), new Figures.PersonFigures(person.name(), claimed.toPlainString(),
                    none ? "n/a" : due.toPlainString(), overdue.toPlainString()));
        }
        return new Figures(figures, claimedTotal.toPlainString(), trimmed(dues).toPlainString(),
                trimmed(overdues).toPlainString());
    }

    /** A sheet total of per-person figures: with three or more, the single highest and lowest are left out. */
    private static BigDecimal trimmed(List<BigDecimal> figures) {
        List<BigDecimal> sorted = figures.stream().sorted().toList();
        List<BigDecimal> kept = sorted.size() >= 3 ? sorted.subList(1, sorted.size() - 1) : sorted;
        return kept.stream().reduce(ZERO, BigDecimal::add);
    }

    /**
     * Each person's due-total for the dates {@code from} to {@code to} inclusive, by person id in sheet order: the
     * figures (as shown now) of their claims due by a date then that counted by the status their log records at the end of
     * {@code to} (a claim added after it counts not at all), those without one skipped.
     */
    public Map<Long, BigDecimal> personDueTotals(String sheetId, LocalDate from, LocalDate to) {
        LocalDate today = sheets.today(sheetId);
        Map<Long, ClaimStatus> ended = claims.statusesOn(sheetId, to);
        List<Claim> dated = claims.list(sheetId).stream()
                .filter(c -> !c.dueBy().isBefore(from) && !c.dueBy().isAfter(to)).toList();
        Map<Long, BigDecimal> totals = new LinkedHashMap<>();
        for (Person person : people.list(sheetId)) {
            BigDecimal total = ZERO;
            for (Claim claim : dated) {
                Claim then = claim.withStatus(ended.getOrDefault(claim.id(), claim.status()), claim.number(),
                        claim.settledDue(), claim.openedBy());
                // A hold leaves out only a claim that is open now.
                boolean left = claim.status().isOpen() ? !counts(then, person, today) : then.deferredOn(today);
                if (claim.personId() != person.id() || !then.status().counts() || left) {
                    continue;
                }
                BigDecimal figure = figure(claim, person, today);
                if (figure != null) {
                    total = total.add(figure);
                }
            }
            totals.put(person.id(), total);
        }
        return totals;
    }

    /** The claim's figure as the screen shows it on the sheet's today (null: n/a), whatever its status. */
    public BigDecimal figure(Claim claim) {
        Person person = people.find(claim.sheetId(), claim.personId());
        return person == null ? claim.settledDue() : figure(claim, person, sheets.today(claim.sheetId()));
    }

    /**
     * Whether the (OPEN, PENDING or SETTLED) claim counts: a person's open claims dated within one of their holds
     * count in no live total, unless a statement bound them, nor do they once {@code today} reaches their retirement date;
     * nor does an OPEN claim deferred on {@code today}.
     */
    public static boolean counts(Claim claim, Person person, LocalDate today) {
        if (claim.deferredOn(today)) {
            return false;
        }
        boolean bound = claim.stated() && claim.status() != ClaimStatus.PENDING;
        return !(claim.status().isOpen() && !bound && (person.heldOn(claim.date()) || person.retiredOn(today)));
    }

    /**
     * The claim's figure (null when it has none): a settled claim's frozen due, otherwise the figure its person's
     * last statement bound it to, otherwise its amount times its person's grade's rate on its date, rounded by the policy date;
     * an overdue claim's late charge on {@code today} added on top of the last two, then raised to the floor.
     */
    private BigDecimal figure(Claim claim, Person person, LocalDate today) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        return settings.withLate(claim, bound(claim, person), today);
    }

    /**
     * The claim's figure before any late charge: the one its person's last statement bound, else its live rate figure (not floored).
     * A PENDING claim is not bound: it shows its live figure until approved or rejected.
     */
    private BigDecimal bound(Claim claim, Person person) {
        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
            return claim.statedDue();
        }
        BigDecimal rate = rates.on(claim.sheetId(), person.gradeOn(claim.date()), claim.date());
        return settings.live(claim, rate);
    }
}
import { useQuery } from '@tanstack/react-query';
import { PersonCells, PersonHeaders } from '../../slots/defs/personColumns';
import { SheetPanel } from '../../slots/defs/sheetPanel';
import { peopleQuery } from '../people/peopleQuery';
import { useSheetToday } from '../sheet/useSheetToday';
import { claimsQuery, counts, sumAmounts } from './claimsQuery';

function useCounting(sheetId: string) {
  const people = useQuery(peopleQuery(sheetId)).data ?? [];
  const today = useSheetToday(sheetId);
  return (useQuery(claimsQuery(sheetId)).data ?? []).filter((c) => counts(c, people, today));
}

function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const claims = useCounting(sheetId);
  return <td data-testid="person-claimed">{sumAmounts(claims.filter((c) => c.personId === personId))}</td>;
}

function ClaimedTotal({ sheetId }: { sheetId: string }) {
  const claims = useCounting(sheetId);
  return (
    <p data-testid="rollup">
      Claimed total <strong data-testid="rollup-claimed-total">{sumAmounts(claims)}</strong>
    </p>
  );
}

export const contributions = [
  PersonHeaders.fill({ order: 10, Component: () => <th>Claimed</th> }),
  PersonCells.fill({ order: 10, Component: PersonClaimed }),
  SheetPanel.fill({ order: 20, Component: ClaimedTotal }),
];
  lines: string[];
};

/** A correction: its due is its amount times the rate, with no floor and no late charge. */
export const isCorrection = (c: Claim) => Number(c.amount) < 0;

/**
 * An OPEN claim deferred to a date the sheet's `today` has not reached: it counts in no total, is not overdue and
 * cannot be settled. From that day on it is an OPEN claim like any other.
 */
export const isDeferred = (c: Claim, today: string) =>
  c.status === 'OPEN' && c.deferredUntil !== null && (today === '' || today < c.deferredUntil);

/**
 * Only open (OPEN or PENDING) and SETTLED claims count toward claimed, due and every total; drafts, voided and
 * deleted ones do not, nor do a person's open claims dated within one of their holds, or once the sheet's `today` reaches
 * their retirement date, unless a statement bound them, nor an OPEN claim deferred on the sheet's `today`.
 */
export const counts = (c: Claim, people: Person[], today: string) =>
  !isDeferred(c, today) &&
  (c.status === 'SETTLED' ||
  (isOpen(c) &&
    ((c.stated && c.status !== 'PENDING') || !leftOut(people.find((p) => p.id === c.personId), c.date, today))));

/** Whether the person's unbound open claim dated `date` is left out: within a hold, or retired by `today`. */
const leftOut = (person: Person | undefined, date: string, today: string) =>
  heldOn(person, date) || (!!person?.retiredFrom && !!today && person.retiredFrom <= today);

/** The first day (yyyy-mm-dd) of the 30 days up to and including the sheet's `today`. */
const activeFrom = (today: string) => new Date(Date.parse(`${today}T00:00:00Z`) - 29 * 86_400_000).toISOString().slice(0, 10);

/**
 * Whether the person is active: they have an open (OPEN or PENDING) claim that counts, dated within the 30 days up to
 * and including the sheet's `today` (never while `today` is not loaded).
 */
export function isActive(personId: number, claims: Claim[], people: Person[], today: string): boolean {
  if (today === '') return false;
  const from = activeFrom(today);
  return claims.some(
    (c) => c.personId === personId && isOpen(c) && counts(c, people, today) && from <= c.date && c.date <= today,
  );
}

